<script setup>defineProps({ selectedText:String, result:Object })</script>
<template><section class="analysis"><h3>语法分析</h3><template v-if="result"><template v-if="result.patterns?.length"><div v-for="g in result.patterns" :key="g.text" class="definition"><span class="pill">{{ g.pattern }}</span><h4>{{ g.text }}</h4><p>语序理解：{{ g.order }}</p><p>{{ g.explanation }}</p></div></template><template v-else><h4>{{ result.sentence_pattern }}</h4><p v-if="result.modern_order">语序理解：{{ result.modern_order }}</p><p>{{ result.explanation }}</p><ul v-if="result.components?.length"><li v-for="part in result.components" :key="part.text">{{ part.text }}：{{ part.role }}</li></ul><details v-if="result.available_patterns?.length"><summary>查看本篇语法条目</summary><div v-for="g in result.available_patterns" :key="g.text" class="definition"><h4>{{ g.text }} · {{ g.pattern }}</h4><p>{{ g.explanation }}</p></div></details></template><p class="result-source">{{ result.source_label || 'AI 生成内容，请结合原文核对' }}</p></template><p v-else class="empty">请选择原文后分析句式。</p></section></template>
